using System;using System.Drawing;using System.Drawing.Imaging;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using CuckooSetup;
class PreviewBackend:IBackend {
 public string Mode; public bool IsUpdate{get{return Mode=="update";}}public bool RuntimeMissing{get{return Mode=="missing";}}public bool ChildActive{get{return false;}}public string LogPath{get{return "検証用ログ";}}
 public Task Install(Action<string> p){p("Cuckooをインストールしています。");var t=new TaskCompletionSource<bool>();if(Mode=="complete")t.SetResult(true);else if(Mode=="failed")t.SetException(new SetupError("NETWORK","接続を確認して、再試行してください。"));else if(Mode=="unknown")t.SetException(new Unconfirmed("処理結果の確認が必要です。"));return t.Task;}
 public Task Uninstall(Action<string> p){return Install(p);}public Task Launch(){return Task.FromResult(true);}
}
class Preview { static string Describe(Control c,int depth){string s=new string(' ',depth)+c.GetType().Name+" "+c.Bounds+" "+c.Text.Replace("\r","").Replace("\n","|")+"\n";foreach(Control child in c.Controls)s+=Describe(child,depth+1);return s;} static void Collect(Control c,System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<Control,Font>> f){f.Add(new System.Collections.Generic.KeyValuePair<Control,Font>(c,c.Font));foreach(Control child in c.Controls)Collect(child,f);} [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string mode=args[0],output=args[1];float scale=float.Parse(args[2],System.Globalization.CultureInfo.InvariantCulture);var backend=new PreviewBackend{Mode=mode};var form=new SetupForm(backend,false,typeof(SetupForm).Assembly.GetName().Version.ToString(3));form.Shown+=(s,e)=>{if(mode!="ready"&&mode!="missing"&&mode!="update"){var b=(Button)typeof(SetupForm).GetField("primary",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(form);b.PerformClick();}if(scale!=1f){var fonts=new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<Control,Font>>();Collect(form,fonts);form.Scale(new SizeF(scale,scale));foreach(var pair in fonts)pair.Key.Font=new Font(pair.Value.FontFamily,pair.Value.SizeInPoints*scale,pair.Value.Style);}var timer=new Timer{Interval=700};timer.Tick+=(a,b)=>{timer.Stop();System.IO.File.WriteAllText(output+".layout.txt",Describe(form,0));using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(output,ImageFormat.Png);}Environment.Exit(0);};timer.Start();};Application.Run(form);}}

